import{_ as e,o as t,c as r,a0 as n}from"./chunks/framework.-mROjw-3.js";const h=JSON.parse('{"title":"卷积神经网络","description":"","frontmatter":{},"headers":[],"relativePath":"卷积神经网络.md","filePath":"卷积神经网络.md"}'),o={name:"卷积神经网络.md"};function _(p,a,i,s,d,c){return t(),r("div",null,[...a[0]||(a[0]=[n('<h1 id="卷积神经网络" tabindex="-1">卷积神经网络 <a class="header-anchor" href="#卷积神经网络" aria-label="Permalink to &quot;卷积神经网络&quot;">​</a></h1><p>这里简要阐述我对CNN的理解，日后如果时间充足，我可能会返回来补充。</p><h2 id="为什么不用全连接层而用cnn" tabindex="-1">为什么不用全连接层而用CNN <a class="header-anchor" href="#为什么不用全连接层而用cnn" aria-label="Permalink to &quot;为什么不用全连接层而用CNN&quot;">​</a></h2><p>卷积神经网络适用于图像处理，为什么不用全连接层呢？原因就是全连接层处理拉直后的图像，参数量巨大。因为全连接层往往吃的是一维度的，再接入全连接层，单纯第一层就已经参数很大了，多层的话参数直接爆炸。</p><p>所以决定使用卷积来处理图像。卷积层做的其实就是用一个卷积核（也叫滤波器），在要处理的图像上从左到右、从上到下滑动，反复识别局部模式。</p><p>卷积比全连接更好，因为卷积有几个突出的优点，比如参数共享，卷积核在扫图的过程中会将参数重复使用，对比全连接层，卷积层省参数特别多。</p><h2 id="填充和步幅" tabindex="-1">填充和步幅 <a class="header-anchor" href="#填充和步幅" aria-label="Permalink to &quot;填充和步幅&quot;">​</a></h2><p>填充：padding</p><p>填充其实就是把原来的图的外围填上一些像素，比如补0，这样可以保护我们内部的原图像，进而在经过卷积层时不丢失信息。</p><p>步幅</p>',10)])])}const m=e(o,[["render",_]]);export{h as __pageData,m as default};
